from typing import Optional

def read_env_file(env_path: str, key: str, default: Optional[str] = None) -> str:
    """
    Read a .env file and return the value of the specified key, or the default if not found.
    """
    if not os.path.exists(env_path):
        raise FileNotFoundError(f"The .env file does not exist at {env_path}")

    with open(env_path, "r") as f:
        for line in f:
            line = line.strip()
            if not line or line.startswith("#"):
                continue
            if "=" in line:
                env_key, env_value = line.split("=", 1)
                env_key = env_key.strip()
                env_value = env_value.strip()
                if env_key == key:
                    return env_value

    return default or ""

