import functools
import time
from typing import Any, Callable, Dict, Optional, TypeVar

T = TypeVar('T')

class TTLCache:
    def __init__(self, maxsize: int = 128, ttl: int = 300):
        self.cache: Dict[str, Any] = {}
        self.maxsize = maxsize
        self.ttl = ttl
        self._lock = functools.Lock()

    def __call__(self, func: Callable[..., T]) -> Callable[..., T]:
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            key = self._generate_key(func, args, kwargs)
            with self._lock:
                if key in self.cache and self._is_cache_valid(self.cache[key]):
                    return self.cache[key]

                result = func(*args, **kwargs)
                self.cache[key] = {
                    'result': result,
                    'timestamp': time.time()
                }
                if len(self.cache) > self.maxsize:
                    self._evict_cache()
                return result

        return wrapper

    def _generate_key(self, func: Callable[..., T], args: tuple, kwargs: dict) -> str:
        return f"{func.__module__}.{func.__name__}:{args}:{kwargs}"

    def _is_cache_valid(self, cache_entry: dict) -> bool:
        return time.time() - cache_entry['timestamp'] < self.ttl

    def _evict_cache(self):
        # Simple LRU eviction (remove the oldest entry)
        if self.cache:
            oldest_key = min(self.cache, key=lambda k: self.cache[k]['timestamp'])
            del self.cache[oldest_key]

    def clear(self):
        self.cache.clear()

