def format_table(records: List[Dict[str, Any]], headers: List[str]) -> str:
    """
    Format a list of records as a table with aligned columns.
    """
    if not records:
        return ""

    # Get the maximum width for each column
    col_widths = [max(len(str(record[col])) for record in records) for col in headers]

    # Create the header row
    header = " | ".join(f"{header:<{col_widths[i]}}" for i, header in enumerate(headers))
    separator = "-+-".join("-" * width for width in col_widths)
    rows = [header, separator]

    # Create the data rows
    for record in records:
        row = " | ".join(f"{str(record[col]):<{col_widths[i]}}" for i, col in enumerate(headers))
        rows.append(row)

    return "\n".join(rows)

@click.command("table")
@click.argument("records", type=str, required=True)
@click.argument("headers", type=str, required=True)
@click.option("--format", default="text", help="Output format (text, json, csv)")
def table_command(records: str, headers: str, format: str) -> None:
    """
    Print a list of records as an aligned table in the terminal.

    RECORDS: JSON string of records (e.g., '[{"name": "Alice", "age": 30}, {"name": "Bob", "age": 25}]')
    HEADERS: Comma-separated list of header names (e.g., "name,age")
    """
    try:
        records_list = eval(records)  # For simplicity, using eval for demo. In production, use json.loads
        headers_list = headers.split(",")

        if not records_list or not headers_list:
            click.echo("Invalid input. Please provide valid records and headers.")
            return

        table = format_table(records_list, headers_list)

        if format == "text":
            click.echo(table)
        elif format == "json":
            click.echo(json.dumps(records_list, indent=2))
        elif format == "csv":
            csv = " | ".join(headers_list) + "\n"
            for record in records_list:
                csv += " | ".join(str(record[col]) for col in headers_list) + "\n"
            click.echo(csv)
        else:
            click.echo(f"Unsupported format: {format}. Use 'text', 'json', or 'csv'.")

    except Exception as e:
        click.echo(f"Error: {str(e)}")

