import time
from functools import wraps

def cache_with_ttl(ttl_seconds: int):
    """
    A decorator that caches the result of a function for a given time-to-live (TTL).
    The cached result is invalidated after the TTL has expired.
    """
    def decorator(func):
        cache = {}

        @wraps(func)
        def wrapper(*args, **kwargs):
            key = (args, frozenset(kwargs.items()))
            current_time = time.time()

            if key in cache:
                # Check if the cached result is still valid
                if current_time - cache[key]["timestamp"] < ttl_seconds:
                    return cache[key]["result"]

            # If not cached or expired, compute and cache the result
            result = func(*args, **kwargs)
            cache[key] = {
                "result": result,
                "timestamp": current_time
            }
            return result

        return wrapper

    return decorator

